// Extract user message and session info
const userMessage = $input.item.json.body.message || "";
const sessionId = $input.item.json.body.sessionId || "unknown";
const timestamp = $input.item.json.body.timestamp || new Date().toISOString();

// Return formatted data for next nodes
return {
  json: {
    userMessage: userMessage,
    sessionId: sessionId,
    timestamp: timestamp,
    conversationContext: "portfolio_assistant"
  }
};

// Build comprehensive context from database results
const dbResults = $input.all();
const contextData = {};

for (const item of dbResults) {
  const dataType = item.json.data_type;
  const data = item.json.data;
  contextData[dataType] = data;
}

// Format context for AI
const profile = contextData.profile || {};
const hero = contextData.hero || {};
const experience = contextData.experience || [];
const skills = contextData.skills || [];
const projects = contextData.projects || [];

const contextText = `
PORTFOLIO OWNER INFORMATION:
Name: ${profile.name || 'Akheel Kappoor'}
Title: ${profile.title || hero.tagline || 'Business Analyst'}
Bio: ${profile.bio || hero.description || ''}
Location: ${profile.location || hero.availability_location || 'Dubai, UAE'}
Email: ${profile.email || ''}
Phone: ${profile.phone || ''}
LinkedIn: ${profile.linkedin || ''}
GitHub: ${profile.github || ''}
Availability: ${hero.availability_status || 'Available'}

WORK EXPERIENCE:
${experience.map((exp, i) => `
${i + 1}. ${exp.position} at ${exp.company}
   Duration: ${exp.duration}
   Location: ${exp.location}
   Description: ${exp.description}`).join('\n')}

SKILLS:
${skills.map(cat => `
- ${cat.category}: ${(cat.items || []).join(', ')}`).join('\n')}

PROJECTS:
${projects.map((proj, i) => `
${i + 1}. ${proj.title}
   Description: ${proj.description}
   Technologies: ${proj.technologies || 'N/A'}
   URL: ${proj.url || 'N/A'}
   GitHub: ${proj.github || 'N/A'}`).join('\n')}
`;

return {
  json: {
    userMessage: $('Extract Message Data').item.json.userMessage,
    sessionId: $('Extract Message Data').item.json.sessionId,
    timestamp: $('Extract Message Data').item.json.timestamp,
    portfolioContext: contextText,
    profileData: profile,
    heroData: hero,
    experienceData: experience,
    skillsData: skills,
    projectsData: projects
  }
};

// Format AI response for chatbot
const aiResponse = $input.item.json.message?.content || $input.item.json.response || "I'm having trouble processing that right now. Please try asking again or contact me directly!";

// Log conversation to database (optional)
const userMessage = $('Extract Message Data').item.json.userMessage;
const sessionId = $('Extract Message Data').item.json.sessionId;
const timestamp = $('Extract Message Data').item.json.timestamp;

return {
  json: {
    response: aiResponse,
    sessionId: sessionId,
    timestamp: new Date().toISOString(),
    metadata: {
      userMessage: userMessage,
      receivedAt: timestamp,
      respondedAt: new Date().toISOString()
    }
  }
};

// Error handling - return friendly error message
const error = $input.item.json.error || "Unknown error";

return {
  json: {
    response: "I apologize, but I'm experiencing technical difficulties right now. 😅 Please try again in a moment or feel free to reach out directly via the contact form!",
    error: error,
    timestamp: new Date().toISOString()
  }
};
